function pcmS16leSampleWindow(
  value: string,
  startSample: number,
  sampleCount: number,
): Int16Array<ArrayBuffer> {
  const samples = new Int16Array(sampleCount);
  for (let index = 0; index < samples.length; index += 1) {
    const byteOffset = (startSample + index) * 4;
    const low = Number.parseInt(value.slice(byteOffset, byteOffset + 2), 16);
    const high = Number.parseInt(value.slice(byteOffset + 2, byteOffset + 4), 16);
    const unsigned = low | (high << 8);
    samples[index] = unsigned >= 0x8000 ? unsigned - 0x10000 : unsigned;
  }
  return samples;
}

